<?php
if (!defined('WP_CLI') || !WP_CLI || wp_get_environment_type() !== 'local') throw new RuntimeException('Local tests only.');
$check = static function ($ok, $label) { if (!$ok) throw new RuntimeException($label); };
$orders = wc_get_orders(['limit' => -1, 'return' => 'ids']);
$original_page = get_option('woocommerce_checkout_page_id');
$_GET['aster_checkout_review'] = '1';
$check(aster_refined_checkout_active(), 'Explicit review active');
$check(!aster_refined_checkout_published(), 'Normal checkout is not silently switched');
$check(apply_filters('woocommerce_ajax_get_endpoint', 'http://localhost/?wc-ajax=update_order_review', '') === 'http://localhost/?wc-ajax=update_order_review&aster_checkout_review=1', 'Native AJAX retains review context');
$check(apply_filters('woocommerce_ajax_get_endpoint', 'http://localhost/?wc-ajax=%%endpoint%%', '') === 'http://localhost/?wc-ajax=%%endpoint%%&aster_checkout_review=1', 'Native JS endpoint placeholder remains replaceable');
$dto = new WooCommerce\PayPalCommerce\Settings\DTO\LocationStylingDTO('classic_checkout');
$dto->methods = ['ppcp-gateway', 'pay-later'];
$styled = apply_filters('option_woocommerce-ppcp-data-styling', ['classic_checkout' => $dto, 'express_checkout' => new WooCommerce\PayPalCommerce\Settings\DTO\LocationStylingDTO('express_checkout')]);
$check($dto->methods === ['ppcp-gateway', 'pay-later'], 'Stored provider DTO is not mutated');
$check($styled['classic_checkout'] !== $dto && $styled['classic_checkout']->color === 'black', 'Review receives a cloned, styled provider DTO');
$check(!$styled['express_checkout']->enabled && !in_array('pay-later', $styled['classic_checkout']->methods, true), 'Duplicate express and Pay Later entry points removed');
$check(apply_filters('option_woocommerce_ppcp-axo-gateway_settings', ['enabled' => 'yes'])['enabled'] === 'no', 'Fastlane disabled only in reviewed flow');
$errors = new WP_Error(); do_action('woocommerce_after_checkout_validation', [], $errors);
$check($errors->get_error_message('aster_layout_review') !== '', 'Review rejects Woo order submission before creation');
$blocked = apply_filters('pre_http_request', false, ['method' => 'POST'], 'https://api-m.sandbox.paypal.com/v2/checkout/orders');
$check(is_wp_error($blocked) && $blocked->get_error_code() === 'aster_layout_review', 'Review blocks provider order writes');
$allowed = apply_filters('pre_http_request', false, ['method' => 'GET'], 'https://api-m.sandbox.paypal.com/v2/checkout/orders/example');
$check($allowed === false, 'Read-only provider calls are not replaced');
unset($_GET['aster_checkout_review']); $_COOKIE['aster_checkout_review'] = '1'; $_SERVER['REQUEST_METHOD'] = 'GET'; $_SERVER['REQUEST_URI'] = '/checkout/';
$check(!aster_refined_checkout_active(), 'Normal checkout GET exits temporary review context');
$_SERVER['REQUEST_METHOD'] = 'POST'; $_SERVER['REQUEST_URI'] = '/?wc-ajax=update_order_review';
$check(aster_refined_checkout_active(), 'Native review AJAX retains its scoped cookie');
unset($_COOKIE['aster_checkout_review']);
$check(get_option('woocommerce_checkout_page_id') === $original_page, 'Published checkout page mapping unchanged');
$check(wc_get_orders(['limit' => -1, 'return' => 'ids']) === $orders, 'No order created by checks');
WP_CLI::success('15 native-checkout review, provider-write, configuration and isolation checks passed. No HTTP payment requests were sent.');
